    # item) and place the new catalogue one level beneath Salary Filing.
    ServicePricing.objects.filter(category=salary.category).update(is_active=True)
    ServicePricing.objects.filter(service_code__in=INCOME_HEAD_CODES).update(
        parent_service=salary, is_active=True,
    )


